import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"内存安全语言迁移","description":"","frontmatter":{"title":"内存安全语言迁移","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memory-safe-languages.md","filePath":"cs/memory-safe-languages.md","lastUpdated":1789023840000}'),c={name:"cs/memory-safe-languages.md"};function u(E,a,m,f,A,_){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="内存安全语言迁移" tabindex="-1">内存安全语言迁移 <a class="header-anchor" href="#内存安全语言迁移" aria-label="Permalink to &quot;内存安全语言迁移&quot;">​</a></h1><div class="epigraph"><p>缓解堆叠提高利用代价；内存安全语言把越界、UAF、数据竞争从语义里删掉。迁移是 TCB 决策：新代码默认安全语言，遗留 C 用边界与沙箱围住。</p><footer>—— 据 Miller 对内存安全的论述；Rust 所有权；seL4 对 C 子集验证的对照；Anderson 对 TCB</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/pointer-authentication">PAC</a>仍假设 C 能写出任意写。缺口是<strong>换语义</strong>：Rust/Go/Java/.NET 等在各自模型里取消空间安全洞（不安全块与运行时漏洞除外）。本课讲迁移策略，不写语言教程。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>C 的对象模型允许本单元全部洞。安全语言：界检查、GC 或借用、类型。缺口是 FFI 与 <code>unsafe</code>：洞从边界再进来。策略：新组件默认安全语言，C 缩进 TCB。</p><h3 id="运行时仍要补丁" tabindex="-1">运行时仍要补丁 <a class="header-anchor" href="#运行时仍要补丁" aria-label="Permalink to &quot;运行时仍要补丁&quot;">​</a></h3><p>GC 实现、JIT、标准库仍是 C/C++ 时，沙箱与更新策略不能停。</p><p><span class="marginnote">Chrome/Android 等公开的语言迁移叙述。seL4 用验证过的 C 子集，是另一条路，本课程最后一课再收。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分绿场与棕场：新服务用安全语言；解析器等攻击面优先重写；FFI 最小化。对照硬件缓解：迁移期仍开。下一课序改「如何发现」：fuzz。</p>',12)),(e(),n(p,null,{default:r(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E6%96%B0%E4%BB%A3%E7%A0%81%22%5D%20--%3E%20SAFE%5B%22%E5%86%85%E5%AD%98%E5%AE%89%E5%85%A8%E8%AF%AD%E8%A8%80%22%5D%0A%20%20OLD%5B%22%E9%81%97%E7%95%99%20C%22%5D%20--%3E%20BOX%5B%22%E6%B2%99%E7%AE%B1%E4%B8%8E%E7%BC%93%E8%A7%A3%22%5D%0A%20%20FFI%5B%22%E8%BE%B9%E7%95%8C%22%5D%20--%3E%20REV%5B%22%E5%AE%A1%E6%9F%A5%E4%B8%8E%E6%B5%8B%E8%AF%95%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>利用课序封口：从栈到硬件到语言。发现与工程课序从覆盖引导 fuzz 起，承认遗留 C 仍在。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较全部语言性能神话。下一课覆盖引导 fuzzing。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PAC/CET 是缓解；安全语言改语义。</li><li>FFI 与运行时仍是 TCB。</li><li>迁移是攻击面排序，不是一天重写内核。</li><li>下一课序：覆盖引导 fuzz。</li><li>出处：Miller 等对内存安全；Rustonomicon 的 unsafe 边界；Anderson；Klein et al. seL4（对照）。</li></ul>',8))])}const T=s(c,[["render",u]]);export{B as __pageData,T as default};
